    if (typeof lat !== 'number' || typeof lon !== 'number') return null;
    if (Math.abs(lat) > 90 || Math.abs(lon) > 180 || (lat === 0 && lon === 0)) return null;
    const mw = o.capacity_mw ?? o.mw ?? o.nameplate_mw ?? o.capacity;
