    if (result.content.some((it) => typeof it?.text === 'string'
        && (it.text.startsWith('\u{1F7E2} Live') || it.text.startsWith('\u{1F7E1} DC Hub grid')))) {
      return result; // idempotent (green live banner OR yellow lagged-grid banner)
    }
